window.MastrifyCopy={"/":[{type:"label",text:"Intelligent mastering engine"},{type:"heading1",text:"Music shaped for release with musical depth"},{type:"paragraph",text:"Intelligent mastering that preserves your punch, space, and character. Your mix, shaped for release."},{type:"link",text:"Start mastering",href:"/master"},{type:"link",text:"Analyze your mix",href:"/analyze"},{type:"link",text:"Why Mastrify",href:"/how-it-works"},{type:"text",text:"No signup required to begin"},{type:"label",text:"Before you master"},{type:"heading2",text:"Understand your mix with clarity"},{type:"paragraph",text:"Perceptual analysis highlights dynamics, balance, and release readiness, so you know what your song needs before the final master."},{type:"link",text:"Run a free mix analysis",href:"/analyze"}],"/how-it-works":[{type:"label",text:"Intelligent mastering"},{type:"heading1",text:"How your music becomes release-ready"},{type:"paragraph",text:"Mastrify listens like an engineer who cares about the song, preserving dynamics, emotional movement, and the identity of your mix while bringing it to a confident, streaming-ready level."},{type:"list",items:["Perceptual processing that follows the music, not a fixed template","Transparency when your material already speaks clearly","Loudness and tone shaped with restraint and intent"]},{type:"link",text:"Start mastering",href:"/master"},{type:"link",text:"Analyze a mix first",href:"/analyze"},{type:"label",text:"The path to your master"},{type:"heading2",text:"Six stages of intelligent care"},{type:"paragraph",text:"Each step is deliberate, built to support your mix, not overwrite it."},{type:"step",number:"01",heading:"Upload your mix",text:"Bring a stereo mix you are proud of. The engine listens to your music as a whole, not just its loudness."},{type:"step",number:"02",heading:"Perceptual analysis",text:"We map dynamics, tone, stereo balance, and energy so decisions follow what the track actually needs."},{type:"step",number:"03",heading:"Dynamic & tonal shaping",text:"Movement and punch are preserved while the chain gently opens clarity where the mix allows it."},{type:"step",number:"04",heading:"Stereo & spatial refinement",text:"Width and depth are adjusted with care, enough presence for release, never a washed-out spread."},{type:"step",number:"05",heading:"Intelligent loudness",text:"Loudness is shaped musically toward your goal, with transparency when the material asks for restraint."},{type:"step",number:"06",heading:"Release-ready master",text:"You receive a polished master that still feels like your mix, ready for streaming and sharing."},{type:"label",text:"Mastering philosophy"},{type:"heading2",text:"Smart transparency, the mix stays yours"},{type:"paragraph",text:"Great mastering is often about what you choose not to do. Mastrify earns each move of the chain, so punch, space, and emotion survive the journey to release."},{type:"feature",heading:"Punch and movement stay",text:"Transient life and groove are treated as musical features, not problems to flatten away."},{type:"feature",heading:"Adapts to your material",text:"Dense, dynamic, or already-loud mixes each get a different amount of care, never a one-size chain."},{type:"feature",heading:"Earned processing",text:"When the mix is already balanced, the engine holds back instead of pushing for effect."},{type:"feature",heading:"Musical loudness",text:"Level is guided toward your target with judgment, not brute-force limiting for a number on a meter."},{type:"feature",heading:"Dynamic material respected",text:"Songs that breathe keep their contrast; the master supports the performance you captured."},{type:"feature",heading:"Reference-aware tone",text:"Optional reference tracks inform subtle tonal balance without copying someone else's level."},{type:"label",text:"Before you upload"},{type:"heading2",text:"Give your mix a little room to breathe"},{type:"paragraph",text:"Clean, unclipped mixes with some dynamic space usually produce the most transparent masters. You do not need to hit a specific peak level, just avoid slamming the bus if you want the most open result."},{type:"paragraph",text:"Already heavily limited or loud? That is fine. The engine reads the material and adapts, supporting what is there instead of fighting it."},{type:"label",text:"Helpful habits"},{type:"list",items:["Leave a little headroom on your stereo bus, not for rules, but for clarity.","Check that nothing is clipping before export; distortion limits what mastering can recover.","Trust your ears: if the mix already feels finished, choose a gentler loudness goal.","Use analyze first if you are unsure, it highlights what the song may need."]},{type:"label",text:"Built for real music"},{type:"heading2",text:"Engineered for trust at every stage"},{type:"badges",items:["Transient-safe processing","Adaptive loudness","Stereo-aware analysis","Musical dynamics preserved","Reference-aware tonal balance","Material-aware decisions"]},{type:"text",text:"Ready when your mix is."},{type:"link",text:"Master your track",href:"/master"}],"/pricing":[{type:"label",text:"Simple, honest pricing"},{type:"heading1",text:"One master. Full quality. No complexity.",lines:["One master.","Full quality. No complexity."],readerRaw:"One master.Full quality. No complexity."},{type:"paragraph",text:"Release-ready mastering without subscriptions, master your track first, then pay when you are ready to export, powered by the same cinematic engine as the rest of Mastrify."},{type:"list",items:["Pay per export, only after your master is ready","No subscriptions or hidden tiers","Full-quality WAV with streaming-ready loudness"]},{type:"link",text:"Start mastering",href:"/master"},{type:"link",text:"Why Mastrify",href:"/how-it-works"},{type:"label",text:"Simple pricing"},{type:"heading2",text:"Studio-quality master"},{type:"paragraph",text:"Master first, pay when your export is ready, no subscription."},{type:"price",text:"$9.00"},{type:"text",text:"per master · no subscription"},{type:"list",items:["Full quality WAV export","Release-ready loudness","Ready for Spotify & streaming","Pay only after your master is ready"]},{type:"link",text:"Start mastering",href:"/master"},{type:"paragraph",text:"Secure checkout via Stripe on the results screen after your master is generated."},{type:"label",text:"What you get"},{type:"list",items:["Full quality WAV export","Streaming-ready loudness","Musical dynamics preserved","AI-assisted mastering engine","No subscription required"]},{type:"paragraph",text:"Studio-quality master. One simple price, more value than the cost suggests."}],"/contact":[{type:"label",text:"Support"},{type:"heading1",text:"Contact"},{type:"paragraph",text:"Questions about mastering, exports, or billing? We typically reply within one business day."},{type:"label",text:"Email"},{type:"email",text:"hello@mastrify.com"},{type:"paragraph",text:"Include your track name and a short note. For export or payment help, mention when you completed your master."},{type:"link",text:"Start mastering",href:"/master"},{type:"link",text:"View pricing",href:"/pricing"},{type:"paragraph",text:"Prefer to explore first?"},{type:"link",text:"See how Mastrify works",href:"/how-it-works"}],"/analyze":[{type:"label",text:"Perceptual mix intelligence"},{type:"heading1",text:"See what your mix actually needs"},{type:"paragraph",text:"Explore dynamics, tone, and stereo balance before your final master."},{type:"list",items:["Find what needs attention.","Keep what already works."]},{type:"steps",items:["1 Upload","2 Analyze","3 Results"]},{type:"text",text:"Drop your track here"},{type:"text",text:"WAV, AIFF, FLAC, MP3, up to 500MB"},{type:"button",text:"Choose file"},{type:"text",text:"or drag and drop"},{type:"feature",heading:"100% free",text:"No credit card"},{type:"feature",heading:"Private & secure",text:"Your files stay yours"},{type:"feature",heading:"Instant results",text:"About 30 seconds"},{type:"link",text:"Why Mastrify",href:"/how-it-works"},{type:"text",text:"Supported formats & tips"}],"/master":[{type:"label",text:"Spatial mastering engine"},{type:"heading1",text:"Release-ready masters with musical depth"},{type:"paragraph",text:"Shape loudness and tone while preserving the punch, space, and character of your mix."},{type:"list",items:["Your style. Your loudness goal.","Musical dynamics, handled with care."]},{type:"steps",items:["1 Upload","2 Settings","3 Master"]},{type:"text",text:"Drop your mix here"},{type:"text",text:"WAV, AIFF, FLAC, MP3, up to 500MB"},{type:"button",text:"Continue to settings"},{type:"button",text:"Choose file"},{type:"text",text:"or drag and drop"},{type:"link",text:"Analyze mix first",href:"/analyze"},{type:"text",text:"Pay only for masters you export · Typically 30 to 60 seconds per render"},{type:"feature",heading:"Musical intelligence",text:"Adapts to your material"},{type:"feature",heading:"Transparent dynamics",text:"Punch and movement preserved"},{type:"feature",heading:"Release-ready",text:"Streaming loudness targets"},{type:"link",text:"Why Mastrify",href:"/how-it-works"},{type:"link",text:"Pricing",href:"/pricing"}]};
